$db=DbPdo::conn();$company=(string)$db->query('SELECT id FROM system_company ORDER BY id LIMIT 1')->fetchColumn();$userId=(string)$db->query('SELECT id FROM auth_users ORDER BY id LIMIT 1')->fetchColumn();if($company===''||$userId==='')throw new RuntimeException('검증할 회사 또는 사용자가 없습니다.');if(session_status()!==PHP_SESSION_ACTIVE)session_start();$_SESSION['user']=['id'=>$userId];$_SESSION['auth_state']=['user_id'=>$userId,'status'=>'NORMAL'];$year=2997;$db->beginTransaction();
